import json

from zscaler.zpa.application_segment import ApplicationSegmentAPI

SEGMENT_ID = "<id>"
CONFIG = {"client": {"customerId": "<id>"}}


class StubResponse:
    def __init__(self, body):
        self._body = body

    def get_body(self):
        return self._body

    def get_results(self):
        return []

    def get_status(self):
        return 200


class StubExecutor:
    """Stands in for RequestExecutor: records requests, replies with an empty body."""

    def __init__(self):
        self.requests = []

    def create_request(self, method, endpoint, body=None, headers=None, params=None,
                       use_raw_data_for_body=False):
        req = {"method": method, "endpoint": endpoint.strip(),
               "body": {} if body is None else body, "params": params or {}}
        self.requests.append(req)
        return req, None

    def execute(self, request, response_type=None, return_raw_response=False):
        return StubResponse({}), None


ex = StubExecutor()
seg, resp, err = ApplicationSegmentAPI(ex, CONFIG).update_segment(
    SEGMENT_ID, description="new description")

put = [r for r in ex.requests if r["method"] == "PUT"][0]
print("PUT body actually sent:")
print(json.dumps(put["body"], indent=2, sort_keys=True))
print("err =", err)
